  "message": "Isolate each row in a savepoint while preserving the caller’s transaction.",
  "rationale": "Each row is flushed inside its own savepoint, and only row-level IntegrityError failures are rejected; begin_nested runs outside the handler so failures flushing the caller’s pending changes propagate. Explicitly starting SQLite’s physical transaction when needed ensures releasing savepoints cannot prevent a later caller rollback from undoing successful inserts.",
  "files": [
    {
      "path": "src/integration.py",
      "content": "from sqlalchemy import Column, Integer, String
from sqlalchemy.exc import IntegrityError
from sqlalchemy.orm import DeclarativeBase
class Base(DeclarativeBase): pass
class Item(Base):
    __tablename__ = 'items'
    id = Column(Integer, primary_key=True)
    name = Column(String, unique=True, nullable=False)

def import_rows(session, records):
    accepted = []
    rejected = []
    for position, row in enumerate(records):
        connection = session.connection(bind_arguments={'mapper': Item})
        # SQLite's legacy transaction mode can otherwise commit an outermost
        # savepoint when it is released, bypassing a later caller rollback.
        if connection.dialect.name == 'sqlite':
            if not connection.connection.driver_connection.in_transaction:
                connection.exec_driver_sql('BEGIN')

        # begin_nested flushes preexisting pending changes before the savepoint.
        savepoint = session.begin_nested()
        try:
            with savepoint:
                item = Item(**row)
                session.add(item)
                session.flush()
        except IntegrityError:
            rejected.append(position)
        else:
            accepted.append(item.id)
    return {'accepted': accepted, 'rejected': rejected}
